/**
 * The visual style variant of a toast notification.
 * Use `undefined` for the default (neutral) style.
 * @public
 */
export type ToastType = 'success' | 'caution' | 'pending' | undefined;
/** @internal */
interface BaseOptions {
    type?: ToastType;
}
/** @internal */
interface WithAction {
    action: string;
    onAction: () => void;
}
/**
 * Options for configuring a toast notification.
 * Optionally includes an action button by providing `action` and `onAction`.
 * @public
 */
export type ToastOptions = BaseOptions | (BaseOptions & WithAction);
/**
 * Displays a toast notification in the Stripe Dashboard.
 *
 * @param message - The text content of the toast.
 * @param options - Optional display options, including visual type and an optional action button.
 * @returns A promise resolving to a controller object with `update` and `dismiss` methods.
 * @public
 */
export type ShowToast = (message: string, options?: ToastOptions) => Promise<{
    /** Updates the content and options of the currently displayed toast. */
    update: (updateMessage: string, updateOptions?: ToastOptions) => void;
    /** Programmatically dismisses the toast. */
    dismiss: () => void;
}>;
/** @public */
export declare const showToast: ShowToast;
export {};
